CREATE DATABASE IF NOT EXISTS archive;
CREATE TABLE IF NOT EXISTS t (a INT NOT NULL, b INT NOT NULL, c VARCHAR(10) NOT NULL, d DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS t (id INT PRIMARY KEY);
ALTER TABLE t ADD COLUMN z DATETIME NULL FIRST;
ALTER TABLE t ADD COLUMN m BIGINT NOT NULL DEFAULT 0 AFTER a;
ALTER TABLE t CHANGE b b2 BIGINT NOT NULL;
ALTER TABLE t CHANGE COLUMN d d INT NOT NULL FIRST;
ALTER TABLE t MODIFY c VARCHAR(10) NOT NULL AFTER d;

CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(10) NOT NULL, bio TEXT);
CREATE TABLE users_copy LIKE users;
CREATE TABLE users_copy_parenthesised (LIKE users);

CREATE TABLE pairs (left_id INT, right_id INT, note TEXT, PRIMARY KEY (left_id, right_id));
CREATE TABLE later_pairs (left_id INT, right_id INT, note TEXT);
ALTER TABLE later_pairs ADD PRIMARY KEY (left_id);

CREATE TABLE old_name (id INT PRIMARY KEY, label TEXT);
CREATE VIEW old_view AS SELECT id, label FROM old_name;
RENAME TABLE old_name TO new_name, old_view TO new_view;
CREATE TABLE moving (id INT PRIMARY KEY);
RENAME TABLE moving TO archive.moved;
